inputs = ['hufegh', 'icixfj', 'xvjw', 'eb', 'vjvxjb']
outputs = ['hdewfwzeh', 'icieyfj', 'jjw', 'wzb', 'vjveyjb']

print("Detailed analysis of changes:")
for i in range(len(inputs)):
    inp = inputs[i]
    out = outputs[i]
    print(f"\nExample {i}: '{inp}' -> '{out}'")

    # Find where they differ
    min_len = min(len(inp), len(out))
    diff_pos = -1
    for j in range(min_len):
        if inp[j] != out[j]:
            diff_pos = j
            break

    if diff_pos == -1:
        if len(inp) != len(out):
            diff_pos = min_len
        else:
            print("  No differences found")
            continue

    print(f"  First difference at position {diff_pos}")
    if diff_pos < len(inp) and diff_pos < len(out):
        print(f"  Character changed: '{inp[diff_pos]}' -> '{out[diff_pos]}'")

    # Show substrings around the difference
    start = max(0, diff_pos - 2)
    end = min(len(inp), diff_pos + 3)
    print(f"  Input context:  '{inp[start:end]}'")
    end = min(len(out), diff_pos + 3)
    print(f"  Output context: '{out[start:end]}'")

